import React, { useState } from "react";

const FERRY_ROUTES = [
  { route: "Ei lauttaa", price: 0 },
  { route: "Helsinki - Travemünde (Finnlines)", price: 1050 },
  { route: "Hanko - Lübeck (Transfennica)", price: 1010 },
  { route: "Hanko - Rostock (Finnlines)", price: 750 },
  { route: "Kotka - Antwerpen (Transfennica)", price: 1800 },
];

const DEFAULT_RATES = {
  domestic_km: 0,
  domestic_rate: 1.45,
  continental_km: 0,
  continental_rate: 1.28,
  fuel_factor: 0.18,
  germany_toll: 0.35,
  benelux_toll: 0.27,
  trailer_rate: 70.0,
  trailer_days: 0,
  trailer_fuel: 0,
  ferry_route: "Ei lauttaa",
  ferry_price: 0,
  other_costs: 0,
  margin_percent: 20,
};

function Row({ label, value, unit = "€", highlight = false }) {
  return (
    <div style={{
      display: "flex",
      justifyContent: "space-between",
      alignItems: "center",
      padding: "8px 0",
      borderBottom: "1px solid rgba(255,255,255,0.04)"
    }}>
      <span style={{ color: highlight ? "#f1f5f9" : "#94a3b8", fontSize: "13px", fontWeight: highlight ? "600" : "400" }}>
        {label}
      </span>
      <span style={{
        color: highlight ? "#f97316" : "#cbd5e1",
        fontWeight: highlight ? "700" : "400",
        fontSize: highlight ? "15px" : "13px",
        fontFamily: "monospace"
      }}>
        {typeof value === "number" ? value.toFixed(2) : value} {unit}
      </span>
    </div>
  );
}

function InputField({ label, field, value, onChange, step = "1", prefix = "" }) {
  return (
    <div>
      <label style={{
        display: "block",
        color: "#94a3b8",
        fontSize: "12px",
        marginBottom: "4px"
      }}>
        {label}
      </label>
      <div style={{ display: "flex", alignItems: "center", gap: "6px" }}>
        {prefix && (
          <span style={{ color: "#64748b", fontSize: "12px" }}>{prefix}</span>
        )}
        <input
          type="number"
          step={step}
          value={value}
          onChange={(e) => onChange(field, parseFloat(e.target.value) || 0)}
          style={{
            width: "100%",
            padding: "8px 12px",
            borderRadius: "6px",
            border: "1px solid #334155",
            background: "#0f172a",
            color: "#f1f5f9",
            fontSize: "13px",
            outline: "none",
            boxSizing: "border-box"
          }}
        />
      </div>
    </div>
  );
}

function CostCalculator() {
  const [rates, setRates] = useState(DEFAULT_RATES);
  const [saved, setSaved] = useState(false);

  const handleChange = (field, value) => {
    setRates(prev => ({ ...prev, [field]: value }));
    setSaved(false);
  };

  const handleFerryChange = (route) => {
    const found = FERRY_ROUTES.find(f => f.route === route);
    setRates(prev => ({
      ...prev,
      ferry_route: route,
      ferry_price: found ? found.price : 0
    }));
    setSaved(false);
  };

  const handleReset = () => {
    setRates(DEFAULT_RATES);
    setSaved(false);
  };

  // ===== LASKENTA =====
  const domestic_cost = rates.domestic_km * rates.domestic_rate;
  const continental_cost = rates.continental_km * rates.continental_rate;
  const fuel_cost = rates.continental_km * rates.fuel_factor;
  const germany_toll_cost = rates.continental_km * rates.germany_toll;
  const benelux_toll_cost = rates.continental_km * rates.benelux_toll;
  const trailer_cost = rates.trailer_rate * rates.trailer_days;
  const ferry_cost = rates.ferry_price;
  const fuel_fill_cost = rates.trailer_fuel;
  const other = rates.other_costs;

  const total_costs =
    domestic_cost +
    continental_cost +
    fuel_cost +
    germany_toll_cost +
    benelux_toll_cost +
    trailer_cost +
    ferry_cost +
    fuel_fill_cost +
    other;

  const margin = rates.margin_percent / 100;
  const selling_price = margin < 1 ? total_costs / (1 - margin) : 0;
  const margin_eur = selling_price - total_costs;

  const sectionStyle = {
    background: "#1e293b",
    border: "1px solid #334155",
    borderRadius: "10px",
    padding: "20px",
    marginBottom: "16px"
  };

  const sectionTitle = {
    color: "#f97316",
    fontSize: "13px",
    fontWeight: "700",
    marginTop: 0,
    marginBottom: "16px",
    textTransform: "uppercase",
    letterSpacing: "0.5px"
  };

  return (
    <div>
      {/* Header */}
      <div style={{
        display: "flex",
        justifyContent: "space-between",
        alignItems: "center",
        marginBottom: "24px"
      }}>
        <div>
          <h1 style={{ color: "#f1f5f9", margin: 0, fontSize: "24px" }}>
            Kustannuslaskin
          </h1>
          <div style={{ color: "#64748b", fontSize: "13px", marginTop: "4px" }}>
            Tarjous- ja katelaskuri
          </div>
        </div>
        <button
          onClick={handleReset}
          style={{
            background: "transparent",
            color: "#94a3b8",
            border: "1px solid #334155",
            padding: "8px 16px",
            borderRadius: "6px",
            cursor: "pointer",
            fontSize: "13px"
          }}
        >
          ↺ Nollaa
        </button>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "1fr 380px", gap: "24px", alignItems: "start" }}>

        {/* ===== VASEN: SYÖTTEET ===== */}
        <div>
          {/* Ajo */}
          <div style={sectionStyle}>
            <h3 style={sectionTitle}>🚛 Ajo</h3>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: "12px" }}>
              <InputField
                label="Kotimaan km"
                field="domestic_km"
                value={rates.domestic_km}
                onChange={handleChange}
              />
              <InputField
                label="Kotimaan hinta €/km"
                field="domestic_rate"
                value={rates.domestic_rate}
                onChange={handleChange}
                step="0.01"
              />
              <div style={{
                background: "rgba(249,115,22,0.05)",
                border: "1px solid rgba(249,115,22,0.1)",
                borderRadius: "6px",
                padding: "8px 12px",
                display: "flex",
                flexDirection: "column",
                justifyContent: "center"
              }}>
                <div style={{ color: "#64748b", fontSize: "11px", marginBottom: "4px" }}>
                  Kotimaan kustannus
                </div>
                <div style={{ color: "#f97316", fontFamily: "monospace", fontSize: "15px", fontWeight: "600" }}>
                  {domestic_cost.toFixed(2)} €
                </div>
              </div>
            </div>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: "12px", marginTop: "12px" }}>
              <InputField
                label="Mantereen km"
                field="continental_km"
                value={rates.continental_km}
                onChange={handleChange}
              />
              <InputField
                label="Mantereen hinta €/km"
                field="continental_rate"
                value={rates.continental_rate}
                onChange={handleChange}
                step="0.01"
              />
              <div style={{
                background: "rgba(249,115,22,0.05)",
                border: "1px solid rgba(249,115,22,0.1)",
                borderRadius: "6px",
                padding: "8px 12px",
                display: "flex",
                flexDirection: "column",
                justifyContent: "center"
              }}>
                <div style={{ color: "#64748b", fontSize: "11px", marginBottom: "4px" }}>
                  Mantereen kustannus
                </div>
                <div style={{ color: "#f97316", fontFamily: "monospace", fontSize: "15px", fontWeight: "600" }}>
                  {continental_cost.toFixed(2)} €
                </div>
              </div>
            </div>
          </div>

          {/* Tiemaksut */}
          <div style={sectionStyle}>
            <h3 style={sectionTitle}>🛣️ Polttoaine & Tiemaksut</h3>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: "12px" }}>
              <InputField
                label="Polttoainekerroin (€/km)"
                field="fuel_factor"
                value={rates.fuel_factor}
                onChange={handleChange}
                step="0.01"
              />
              <InputField
                label="Saksa tiemaksukerroin (€/km)"
                field="germany_toll"
                value={rates.germany_toll}
                onChange={handleChange}
                step="0.01"
              />
              <InputField
                label="Hollanti+Saksa kerroin (€/km)"
                field="benelux_toll"
                value={rates.benelux_toll}
                onChange={handleChange}
                step="0.01"
              />
            </div>
            <div style={{
              display: "grid",
              gridTemplateColumns: "1fr 1fr 1fr",
              gap: "12px",
              marginTop: "12px",
              padding: "12px",
              background: "rgba(0,0,0,0.2)",
              borderRadius: "6px"
            }}>
              <div style={{ textAlign: "center" }}>
                <div style={{ color: "#64748b", fontSize: "11px" }}>Polttoaine</div>
                <div style={{ color: "#cbd5e1", fontFamily: "monospace", marginTop: "2px" }}>
                  {fuel_cost.toFixed(2)} €
                </div>
              </div>
              <div style={{ textAlign: "center" }}>
                <div style={{ color: "#64748b", fontSize: "11px" }}>Saksa tiemaksu</div>
                <div style={{ color: "#cbd5e1", fontFamily: "monospace", marginTop: "2px" }}>
                  {germany_toll_cost.toFixed(2)} €
                </div>
              </div>
              <div style={{ textAlign: "center" }}>
                <div style={{ color: "#64748b", fontSize: "11px" }}>Hollanti+Saksa</div>
                <div style={{ color: "#cbd5e1", fontFamily: "monospace", marginTop: "2px" }}>
                  {benelux_toll_cost.toFixed(2)} €
                </div>
              </div>
            </div>
          </div>

          {/* Traileri */}
          <div style={sectionStyle}>
            <h3 style={sectionTitle}>🚌 Traileri</h3>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: "12px" }}>
              <InputField
                label="Trailerin vuokra €/pv"
                field="trailer_rate"
                value={rates.trailer_rate}
                onChange={handleChange}
                step="0.5"
              />
              <InputField
                label="Traileripäivät"
                field="trailer_days"
                value={rates.trailer_days}
                onChange={handleChange}
              />
              <InputField
                label="Trailerin tankkaus €"
                field="trailer_fuel"
                value={rates.trailer_fuel}
                onChange={handleChange}
              />
            </div>
          </div>

          {/* Lautta */}
          <div style={sectionStyle}>
            <h3 style={sectionTitle}>⛴️ Lautta</h3>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "12px" }}>
              <div>
                <label style={{ display: "block", color: "#94a3b8", fontSize: "12px", marginBottom: "4px" }}>
                  Lauttareitti
                </label>
                <select
                  value={rates.ferry_route}
                  onChange={(e) => handleFerryChange(e.target.value)}
                  style={{
                    width: "100%",
                    padding: "8px 12px",
                    borderRadius: "6px",
                    border: "1px solid #334155",
                    background: "#0f172a",
                    color: "#f1f5f9",
                    fontSize: "13px",
                    outline: "none"
                  }}
                >
                  {FERRY_ROUTES.map(f => (
                    <option key={f.route} value={f.route}>
                      {f.route}{f.price > 0 ? ` — ${f.price} €` : ""}
                    </option>
                  ))}
                </select>
              </div>
              <div>
                <label style={{ display: "block", color: "#94a3b8", fontSize: "12px", marginBottom: "4px" }}>
                  Lauttahinta € (muokattavissa)
                </label>
                <input
                  type="number"
                  value={rates.ferry_price}
                  onChange={(e) => handleChange("ferry_price", parseFloat(e.target.value) || 0)}
                  style={{
                    width: "100%",
                    padding: "8px 12px",
                    borderRadius: "6px",
                    border: "1px solid #334155",
                    background: "#0f172a",
                    color: "#f1f5f9",
                    fontSize: "13px",
                    outline: "none",
                    boxSizing: "border-box"
                  }}
                />
              </div>
            </div>
          </div>

          {/* Muut */}
          <div style={sectionStyle}>
            <h3 style={sectionTitle}>📋 Muut kulut</h3>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "12px" }}>
              <InputField
                label="Muut kulut €"
                field="other_costs"
                value={rates.other_costs}
                onChange={handleChange}
              />
              <InputField
                label="Kateprosentti %"
                field="margin_percent"
                value={rates.margin_percent}
                onChange={handleChange}
                step="0.5"
              />
            </div>
          </div>
        </div>

        {/* ===== OIKEA: YHTEENVETO ===== */}
        <div style={{ position: "sticky", top: "24px" }}>
          <div style={{
            background: "#1e293b",
            border: "1px solid #334155",
            borderRadius: "12px",
            padding: "24px"
          }}>
            <h3 style={{
              color: "#f97316",
              fontSize: "14px",
              fontWeight: "700",
              margin: "0 0 20px",
              textTransform: "uppercase",
              letterSpacing: "0.5px"
            }}>
              📊 Laskelma
            </h3>

            {/* Erittely */}
            <div style={{ marginBottom: "16px" }}>
              <div style={{ color: "#475569", fontSize: "11px", textTransform: "uppercase", letterSpacing: "0.5px", marginBottom: "8px" }}>
                Kuluerittely
              </div>
              {domestic_cost > 0 && <Row label="Kotimaan ajo" value={domestic_cost} />}
              {continental_cost > 0 && <Row label="Mantereen ajo" value={continental_cost} />}
              {fuel_cost > 0 && <Row label="Polttoainelisä" value={fuel_cost} />}
              {germany_toll_cost > 0 && <Row label="Saksan tiemaksu" value={germany_toll_cost} />}
              {benelux_toll_cost > 0 && <Row label="Hollanti+Saksa" value={benelux_toll_cost} />}
              {trailer_cost > 0 && <Row label="Trailervuokra" value={trailer_cost} />}
              {fuel_fill_cost > 0 && <Row label="Trailerin tankkaus" value={fuel_fill_cost} />}
              {ferry_cost > 0 && <Row label="Lauttakustannus" value={ferry_cost} />}
              {other > 0 && <Row label="Muut kulut" value={other} />}
              {total_costs === 0 && (
                <div style={{ color: "#475569", fontSize: "13px", padding: "8px 0" }}>
                  Syötä arvot vasemmalle...
                </div>
              )}
            </div>

            {/* Yhteensä-viiva */}
            <div style={{
              borderTop: "2px solid #334155",
              paddingTop: "12px",
              marginBottom: "16px"
            }}>
              <Row label="KULUT YHTEENSÄ" value={total_costs} highlight />
            </div>

            {/* Kate ja myyntihinta */}
            <div style={{
              background: "rgba(249,115,22,0.05)",
              border: "1px solid rgba(249,115,22,0.15)",
              borderRadius: "8px",
              padding: "16px",
              marginBottom: "16px"
            }}>
              <div style={{
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                marginBottom: "8px"
              }}>
                <span style={{ color: "#94a3b8", fontSize: "13px" }}>Kate %</span>
                <span style={{ color: "#f97316", fontFamily: "monospace", fontWeight: "600" }}>
                  {rates.margin_percent} %
                </span>
              </div>
              <div style={{
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                marginBottom: "8px"
              }}>
                <span style={{ color: "#94a3b8", fontSize: "13px" }}>Kate €</span>
                <span style={{ color: "#22c55e", fontFamily: "monospace", fontWeight: "600" }}>
                  {margin_eur.toFixed(2)} €
                </span>
              </div>
              <div style={{
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                borderTop: "1px solid rgba(249,115,22,0.15)",
                paddingTop: "10px",
                marginTop: "4px"
              }}>
                <span style={{ color: "#f1f5f9", fontSize: "15px", fontWeight: "700" }}>
                  MYYNTIHINTA
                </span>
                <span style={{
                  color: "#f97316",
                  fontSize: "22px",
                  fontWeight: "700",
                  fontFamily: "monospace"
                }}>
                  {selling_price.toFixed(2)} €
                </span>
              </div>
            </div>

            {/* Nollaa-nappi */}
            <button
              onClick={handleReset}
              style={{
                width: "100%",
                background: "transparent",
                color: "#64748b",
                border: "1px solid #334155",
                padding: "10px",
                borderRadius: "6px",
                cursor: "pointer",
                fontSize: "13px"
              }}
            >
              ↺ Nollaa laskelma
            </button>
          </div>

          {/* Ohje */}
          <div style={{
            background: "rgba(255,255,255,0.02)",
            border: "1px solid #334155",
            borderRadius: "8px",
            padding: "16px",
            marginTop: "12px"
          }}>
            <div style={{ color: "#64748b", fontSize: "12px", lineHeight: "1.6" }}>
              <div style={{ color: "#94a3b8", fontWeight: "600", marginBottom: "6px" }}>
                Ohjeet:
              </div>
              <div>1. Syötä kotimaan km (Suomen sisäinen ajo)</div>
              <div>2. Syötä mantereen km (Euroopan ajo)</div>
              <div>3. Tarkista kertoimet (muuta tarvittaessa)</div>
              <div>4. Valitse lauttareitti (tai syötä hinta käsin)</div>
              <div>5. Aseta haluamasi kateprosentti</div>
              <div style={{ marginTop: "6px", color: "#475569" }}>
                Myyntihinta lasketaan: Kulut ÷ (1 - Kate%)
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default CostCalculator;
